// =========================
// ADMIN PANEL API V2
// =========================

async function requireAdmin(request, env) {
  const auth = request.headers.get("Authorization") || "";

  if (!auth.startsWith("Bearer ")) {
    return { ok: false, response: json({ success: false, message: "نیاز به ورود مدیر دارید" }, 401, cors) };
  }

  const token = auth.slice(7).trim();

  if (!token) {
    return { ok: false, response: json({ success: false, message: "توکن نامعتبر است" }, 401, cors) };
  }

  const session = await env.DB
    .prepare(`
      SELECT
        s.id,
        s.token,
        s.user_id,
        s.expires_at,
        u.phone,
        u.name,
        u.is_admin
      FROM admin_sessions s
      INNER JOIN users u ON u.id = s.user_id
      WHERE s.token = ?
      LIMIT 1
    `)
    .bind(token)
    .first();

  if (!session || Number(session.is_admin) !== 1) {
    return { ok: false, response: json({ success: false, message: "دسترسی مدیر مجاز نیست" }, 403, cors) };
  }

  if (new Date(session.expires_at).getTime() <= Date.now()) {
    await env.DB
      .prepare("DELETE FROM admin_sessions WHERE token = ?")
      .bind(token)
      .run();

    return { ok: false, response: json({ success: false, message: "نشست مدیر منقضی شده است" }, 401, cors) };
  }

  return { ok: true, session };
}

// ADMIN LOGIN
if (path === "/api/admin/login" && request.method === "POST") {
  const body = await request.json();
  const phone = String(body.phone || "").trim();
  const password = String(body.password || "");

  const user = await env.DB
    .prepare(`
      SELECT id, phone, name, password_hash, is_admin
      FROM users
      WHERE phone = ?
      LIMIT 1
    `)
    .bind(phone)
    .first();

  if (!user || Number(user.is_admin) !== 1) {
    return json({
      success: false,
      message: "اطلاعات مدیر صحیح نیست"
    }, 401, cors);
  }

  const valid = await verifyPassword(password, user.password_hash);

  if (!valid) {
    return json({
      success: false,
      message: "اطلاعات مدیر صحیح نیست"
    }, 401, cors);
  }

  const token = crypto.randomUUID();
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

  await env.DB
    .prepare(`
      INSERT INTO admin_sessions (token, user_id, expires_at)
      VALUES (?, ?, ?)
    `)
    .bind(token, user.id, expiresAt)
    .run();

  return json({
    success: true,
    token,
    user: {
      id: user.id,
      phone: user.phone,
      name: user.name,
      is_admin: 1
    }
  }, 200, cors);
}

// ADMIN LOGOUT
if (path === "/api/admin/logout" && request.method === "POST") {
  const auth = request.headers.get("Authorization") || "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7).trim() : "";

  if (token) {
    await env.DB
      .prepare("DELETE FROM admin_sessions WHERE token = ?")
      .bind(token)
      .run();
  }

  return json({ success: true }, 200, cors);
}

// ADMIN: LIST COURSES
if (path === "/api/admin/courses" && request.method === "GET") {
  const auth = await requireAdmin(request, env);
  if (!auth.ok) return auth.response;

  const { results } = await env.DB
    .prepare(`
      SELECT *
      FROM courses
      ORDER BY id DESC
    `)
    .all();

  return json({ success: true, courses: results }, 200, cors);
}

// ADMIN: CREATE COURSE
if (path === "/api/admin/courses" && request.method === "POST") {
  const auth = await requireAdmin(request, env);
  if (!auth.ok) return auth.response;

  const body = await request.json();

  const title = String(body.title || "").trim();
  const category = String(body.category || "سایر").trim();
  const level = String(body.level || "مقدماتی").trim();
  const description = String(body.description || "").trim();
  const image = String(body.image || "").trim();
  const isFree = Number(body.is_free) ? 1 : 0;
  const price = isFree ? 0 : Math.max(0, Number(body.price) || 0);

  if (!title) {
    return json({ success: false, message: "عنوان دوره الزامی است" }, 400, cors);
  }

  const result = await env.DB
    .prepare(`
      INSERT INTO courses
      (title, category, level, price, is_free, image, description)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `)
    .bind(title, category, level, price, isFree, image, description)
    .run();

  const course = await env.DB
    .prepare("SELECT * FROM courses WHERE id = ?")
    .bind(result.meta.last_row_id)
    .first();

  return json({ success: true, course }, 201, cors);
}

// ADMIN: UPDATE COURSE
const adminCourseMatch = path.match(/^\/api\/admin\/courses\/(\d+)$/);

if (adminCourseMatch && request.method === "PUT") {
  const auth = await requireAdmin(request, env);
  if (!auth.ok) return auth.response;

  const courseId = Number(adminCourseMatch[1]);
  const body = await request.json();

  const title = String(body.title || "").trim();
  const category = String(body.category || "سایر").trim();
  const level = String(body.level || "مقدماتی").trim();
  const description = String(body.description || "").trim();
  const image = String(body.image || "").trim();
  const isFree = Number(body.is_free) ? 1 : 0;
  const price = isFree ? 0 : Math.max(0, Number(body.price) || 0);

  if (!title) {
    return json({ success: false, message: "عنوان دوره الزامی است" }, 400, cors);
  }

  const result = await env.DB
    .prepare(`
      UPDATE courses
      SET title = ?, category = ?, level = ?, price = ?,
          is_free = ?, image = ?, description = ?
      WHERE id = ?
    `)
    .bind(title, category, level, price, isFree, image, description, courseId)
    .run();

  if (!result.meta.changes) {
    return json({ success: false, message: "دوره پیدا نشد" }, 404, cors);
  }

  const course = await env.DB
    .prepare("SELECT * FROM courses WHERE id = ?")
    .bind(courseId)
    .first();

  return json({ success: true, course }, 200, cors);
}

